using ProyectoFinal.Services; namespace ProyectoFinal.Views; public partial class AlertsPage:ContentPage { readonly ProductStore store=new(); public AlertsPage(){InitializeComponent();} protected override async void OnAppearing(){base.OnAppearing();var items=(await store.GetAsync()).Where(p=>!p.IsConsumed&&p.DaysUntilExpiration<=3).OrderBy(p=>p.ExpirationDate).ToList(); AlertList.ItemsSource=items; Summary.Text=items.Count==0?"No tienes productos próximos a vencer.":$"Tienes {items.Count} producto(s) que requieren atención.";} }
